import type { FC } from 'react';
import { useEffect, useState } from 'react';
import { Trash2 } from 'lucide-react';
import ToolLayout from '@/components/tools/ToolLayout';
import UploadBox from '@/components/tools/image-to-pdf/UploadBox';
import ImageGrid from '@/components/tools/image-to-pdf/ImageGrid';
import ConversionResult from '@/components/tools/image-to-pdf/ConversionResult';
import QualitySlider from '@/components/tools/image-converter/QualitySlider';
import { usePersistentState } from '@/hooks/usePersistentState';
import { buildPdfFromImages, type BuildPdfProgress, type PickedImage } from '@/lib/pdf/fromImages';

const ImageToPdf: FC = () => {
  const [images, setImages] = usePersistentState<PickedImage[]>('image-to-pdf:images', []);
  const [quality, setQuality] = usePersistentState<number>('image-to-pdf:quality', 90);

  const [pdfBlob, setPdfBlob] = useState<Blob | null>(null);
  const [progress, setProgress] = useState<BuildPdfProgress | null>(null);
  const [error, setError] = useState<string | null>(null);

  // A generated PDF only reflects the image set/order/quality at the moment
  // it was built — once any of that changes, drop the stale result so the UI
  // goes back to the "Generate PDF" prompt instead of offering an out-of-date download.
  useEffect(() => {
    setPdfBlob(null);
    setError(null);
  }, [images, quality]);

  const handleAdd = (files: File[]) => {
    const added: PickedImage[] = files.map((file) => ({ id: crypto.randomUUID(), file }));
    setImages((prev) => [...prev, ...added]);
  };

  const handleRemove = (id: string) => setImages((prev) => prev.filter((img) => img.id !== id));
  const handleClearAll = () => setImages([]);

  const handleGenerate = () => {
    setError(null);
    setProgress({ index: 0, total: images.length });

    buildPdfFromImages(
      images.map((img) => img.file),
      quality,
      setProgress,
    )
      .then((blob) => {
        setPdfBlob(blob);
        setProgress(null);
      })
      .catch((err: Error) => {
        setError(err.message || "These images couldn't be converted");
        setProgress(null);
      });
  };

  const fileName =
    images.length === 1
      ? `${images[0].file.name.replace(/\.[^./]+$/, '') || 'image'}.pdf`
      : 'merged-images.pdf';

  return (
    <ToolLayout
      title="Image to PDF Converter"
      description="Turn one or more images into an A4 PDF — drag to reorder, then merge them into a single file, entirely in your browser."
    >
      <div className="max-w-2xl space-y-6">
        {images.length > 0 ? (
          <div className="flex items-center justify-between gap-4">
            <h2 className="text-sm font-medium text-muted-foreground">
              {images.length} {images.length === 1 ? 'image' : 'images'}
            </h2>
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={handleClearAll}
                className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-full text-sm font-medium text-muted-foreground hover:text-foreground hover:bg-accent/5 transition-colors"
              >
                <Trash2 className="w-4 h-4" />
                Delete all
              </button>
              <UploadBox compact count={images.length} onAdd={handleAdd} />
            </div>
          </div>
        ) : (
          <UploadBox count={images.length} onAdd={handleAdd} />
        )}

        <ImageGrid images={images} onReorder={setImages} onRemove={handleRemove} />

        {images.length > 0 && <QualitySlider quality={quality} onChange={setQuality} />}

        <ConversionResult
          imageCount={images.length}
          pdfBlob={pdfBlob}
          fileName={fileName}
          progress={progress}
          error={error}
          onGenerate={handleGenerate}
        />
      </div>
    </ToolLayout>
  );
};

export default ImageToPdf;
